      _vertexCount: regionSplats,
      _splatsData: null,
      _shData: null,
      _shDegree: 0,
      isCompound: false,
      getWorldMatrix: () => worldMatrix,
      getBoundingInfo: () => new BoundingInfo(Vector3.ZeroReadOnly, Vector3.ZeroReadOnly),
