      proxy,
      base: alignedBase,
      partIndex: assignedPartIndices[0],
      capacity: alignedCapacity,
      boundsMin,
      boundsMax,
      localRanges: null,
      shTextureCount: shTextureCount > 0 && shDegree > 0 ? shTextureCount : 0,
      shDegree: shTextureCount > 0 && shDegree > 0 ? shDegree : 0,
